def process(filter_wollaston) -> pd.DataFrame:
    total_samples = len(filter_wollaston)
    non_violations = filter_wollaston[filter_wollaston['Violation'].isin(['NO', 'No'])].shape[0]
    percentage = round(100 * non_violations / total_samples)
    return pd.DataFrame({'Total Samples': [total_samples], 'Met Standards': [non_violations], 'Percentage': [percentage]})

def process(filter_wollaston) -> pd.DataFrame:
    total = len(filter_wollaston)
    met_standards = len(filter_wollaston[filter_wollaston['Violation'].str.upper() == 'NO'])
    percentage = int(round(100 * met_standards / total)) if total > 0 else 0
    return pd.DataFrame({
        'Total Samples': [total],
        'Met Standards': [met_standards],
        'Percentage': [percentage]
    })
